import numpy as np 
import matplotlib.pyplot as plt 

def step(x): 
    return np.where(x >= 0, 1, 0) 

def sigmoid(x): 
    return 1 / (1 + np.exp(-x)) 

def tanh(x): 
    return np.tanh(x) 

def relu(x): 
    return np.maximum(0, x) 


# Generate input values 
x = np.linspace(-10, 10, 1000) 

# Compute outputs 
y_step = step(x) 
y_sigmoid = sigmoid(x) 
y_tanh = tanh(x) 
y_relu = relu(x) 


# Create plots 
plt.figure(figsize=(14, 10)) 

functions = [ 
    ('Step', y_step), 
    ('Sigmoid', y_sigmoid), 
    ('Tanh', y_tanh), 
    ('ReLU', y_relu) 
] 


for i, (name, y_vals) in enumerate(functions, 1): 

    plt.subplot(2, 2, i) 

    plt.plot(x, y_vals, linewidth=2) 

    plt.axhline(y=0, linestyle='--', alpha=0.5) 
    plt.axvline(x=0, linestyle='-', alpha=0.5) 

    plt.title(f'{name} Activation Function') 
    plt.xlabel('Input') 
    plt.ylabel('Output') 

    plt.grid(True, alpha=0.3) 

    if name != 'ReLU': 
        plt.ylim(-1.5, 1.5) 
    else: 
        plt.ylim(-1, 5) 


# Print properties 
for name, y_vals in functions: 

    print(f'\n{name}:') 
    print(f'Output range: [{y_vals.min():.2f}, {y_vals.max():.2f}]') 

    print( 
        f"Differentiable: {'No' if name == 'Step' else 'Yes'}" 
    ) 

    if name != 'Step': 

        if name == 'Sigmoid': 
            derivative = "o(x) * (1 - o(x))" 

        elif name == 'Tanh': 
            derivative = "1 - tanh(x)^2" 

        else: 
            derivative = "0 if x < 0, 1 if x > 0" 

        print(f'Derivative: {derivative}') 



plt.tight_layout() 
plt.show()
